-- Pickup zones for every origin country: each US state (and DC), Canadian province, Japanese region, emirate and UK
-- region, to every export port of its country. Generated by backend/tools/generate_pickup_zones.py from the road
-- distance (great circle x 1.2, plus the sea leg for islands) and typical car-hauler tariffs; route planning picks
-- the cheapest port unless the buyer chooses one.
DELETE FROM inland_transport_rate WHERE pickup_zone <> '*';
